<script setup lang="ts">const props=defineProps<{attributes:Record<string,string|number|boolean>}>();const entries=computed(()=>Object.entries(props.attributes));const summary=computed(()=>entries.value.slice(0,3));</script>
<template><section aria-labelledby="post-attributes-title"><h2 id="post-attributes-title">ویژگی‌ها و مشخصات</h2><dl class="post-summary"><div v-for="([key,value]) in summary" :key="key"><dt>{{ key }}</dt><dd>{{ typeof value==='boolean'?(value?'دارد':'ندارد'):value }}</dd></div></dl><dl class="post-attributes"><div v-for="([key,value]) in entries.slice(3)" :key="key"><dt>{{ key }}</dt><dd>{{ typeof value==='boolean'?(value?'✓':'—'):value }}</dd></div></dl></section></template>
